import { PrismaClient } from '@prisma/client';
import { hash } from 'bcryptjs';
import 'dotenv/config';
import readline from 'readline';

const prisma = new PrismaClient();

async function main() {
  const adminName = await ask('Admin username: ');
  const adminEmail = await ask('Admin email: ');
  const adminPassword = await ask('Admin password: ');

  if (adminName && adminEmail && adminPassword) {
    const passwordHash = await hash(adminPassword, 10);
    await prisma.adminUser.upsert({
      where: { name: adminName },
      update: { email: adminEmail, passwordHash },
      create: { name: adminName, email: adminEmail, passwordHash }
    });
  }

  
  await prisma.mediaItem.deleteMany();

  await prisma.mediaItem.createMany({
    data: [
      {
        title: 'Praia',
        imageUrl: '/files/1770564468036-e3e2fd6521aa8f21.jpg',
        audioBase64: '',
        audioMimeType: 'audio/mpeg'
      },
      {
        title: 'Por do Sol',
        imageUrl: '/files/1770564567150-aecf280b50872af1.jpg',
        audioBase64: '',
        audioMimeType: 'audio/mpeg'
      },
      {
        title: 'Rocha no Mar',
        imageUrl: '/files/1770565343380-dbd43d18d070f6df.jpg',
        audioBase64: '',
        audioMimeType: 'audio/mpeg'
      }
    ]
  });
  
}

function ask(question: string): Promise<string> {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
  });

  return new Promise((resolve) => {
    rl.question(question, (answer) => {
      rl.close();
      resolve(answer.trim());
    });
  });
}

main()
  .then(() => prisma.$disconnect())
  .catch(async (e) => {
    console.error(e);
    await prisma.$disconnect();
    process.exit(1);
  });
